using System.Text.Json;
using AshenSpire.Presentation;
var passed=0;
void Check(bool ok,string name){if(!ok)throw new Exception(name);passed++;Console.WriteLine("PASS: "+name);}

// 1. The C# decider answers exactly what the JS game's own layoutForCap/formFactorFor answers
//    (UnityTests/Viewport/js-layout-oracle.json, generated by tools/unity-viewport-oracle.mjs).
var oraclePath=Path.Combine(AppContext.BaseDirectory,"js-layout-oracle.json");
using(var oracle=JsonDocument.Parse(File.ReadAllText(oraclePath)))
{
    Check(oracle.RootElement.GetProperty("commit").GetString()==JsUiTokens.SourceCommit,"oracle and generated tokens come from the same JS commit");
    var rows=oracle.RootElement.GetProperty("rows");var mismatches=new List<string>();var count=0;
    foreach(var row in rows.EnumerateArray())
    {
        var cap=row[0].GetDouble();var w=row[1].GetDouble();var h=row[2].GetDouble();
        var got=ViewportLayout.Resolve(w,h,cap==0?double.PositiveInfinity:cap);
        var ok=Math.Abs(got.Zoom-row[3].GetDouble())<1e-9&&got.Narrow==(row[4].GetInt32()==1)&&got.Compact==(row[5].GetInt32()==1)&&got.Short==(row[6].GetInt32()==1)&&got.FormFactor==row[7].GetString();
        if(!ok&&mismatches.Count<10)mismatches.Add($"{w}x{h} cap {cap}: C# {got.Zoom}/{got.Narrow}/{got.Compact}/{got.Short}/{got.FormFactor} vs JS {row}");
        count++;
    }
    foreach(var m in mismatches)Console.WriteLine("MISMATCH "+m);
    Check(count>1000&&mismatches.Count==0,$"{count} viewport x UI-size cases match the JS layout decider");
}

// 2. Reference points named in the port audit and the JS source comments.
Check(ViewportLayout.Resolve(1280,720).Zoom==0.99&&!ViewportLayout.Resolve(1280,720).Narrow,"1280x720 is wide at zoom 0.99");
Check(ViewportLayout.Resolve(1280,800).Zoom==1.07,"1280x800 keeps the wide rounding (1.07, tools/tutorial-reach guard)");
Check(ViewportLayout.Resolve(390,844).Zoom==0.9&&ViewportLayout.Resolve(390,844).Narrow,"390x844 is narrow and floors 0.907 to 0.90");
Check(ViewportLayout.Resolve(520,900).Narrow&&!ViewportLayout.Resolve(521,900).Narrow,"narrow is width-owned at 520 CSS px");
Check(ViewportLayout.Resolve(844,390).Compact&&!ViewportLayout.Resolve(844,390).Short,"landscape phone is the compact short-wide composition");
Check(ViewportLayout.Resolve(1440,900).ReferenceWidth==1200&&ViewportLayout.Resolve(390,844).ReferenceWidth==430,"the wide and narrow PanelSettings reference sizes follow the mode");
Check(ViewportLayout.Resolve(0,0).Zoom==1&&ViewportLayout.Resolve(double.NaN,900).Zoom==1,"unmeasured viewports answer zoom 1");

// 3. Expand (min of the ratios) is the JS fit, so PanelSettings.scale = zoom / fit lands the panel on the JS zoom.
foreach(var (w,h) in new[]{(1280.0,720.0),(390.0,844.0),(844.0,390.0),(2560.0,1080.0)})
{
    var layout=ViewportLayout.Resolve(w,h);
    var fit=ViewportLayout.PanelFit(w,h,layout.ReferenceWidth,layout.ReferenceHeight,2,0);
    var cssPerPanel=fit*(layout.Zoom/fit);
    Check(Math.Abs(cssPerPanel-layout.Zoom)<1e-12&&Math.Abs(w/cssPerPanel-w/layout.Zoom)<1e-6,$"{w}x{h}: panel is {w/layout.Zoom:0.#}x{h/layout.Zoom:0.#} USS px at zoom {layout.Zoom}");
}
Check(Math.Abs(ViewportLayout.PanelFit(1000,500,1000,1000,0,1)-.5)<1e-12&&Math.Abs(ViewportLayout.PanelFit(1000,500,1000,1000,1,0)-1)<1e-12,"match-height and shrink factors follow Unity's PanelSettings");

// 4. Touch floor: a control reaches at least 44 displayed CSS px, with less than one panel px of rounding.
foreach(var scale in new[]{0.62,0.74,0.9,0.99,1.2,1.7})
{
    var ui=ViewportLayout.MinimumTouchHeight(scale);
    Check(ui*scale>=44-1e-9&&ui*scale<44+scale,$"zoom {scale}: {ui} panel px shows as {ui*scale:0.##} CSS px");
}
Check(ViewportLayout.MinimumTouchHeight(1)==44&&ViewportLayout.MinimumTouchHeight(0.62)==71,"tap floor divides by the zoom (JS --tap-floor)");
Check(float.IsFinite(ViewportLayout.MinimumTouchHeight(0))&&float.IsFinite(ViewportLayout.MinimumTouchHeight(-1))&&float.IsFinite(ViewportLayout.MinimumTouchHeight(double.NaN)),"unmeasured scale stays finite");
Console.WriteLine($"Viewport: {passed} checks passed");
